-- Agency payment abstraction layer. Prepare/review before production apply.
create table if not exists logistics_agency_payment_providers (provider_id text primary key, agency_id text not null, provider_name text not null, provider_type text not null, terminal_id text, location_id text, currency text not null default 'USD', integration_mode text not null default 'REFERENCE_ONLY', status text not null default 'active', created_by_owner_id text, created_at timestamptz not null, updated_at timestamptz not null);
create index if not exists idx_agency_payment_provider_tenant on logistics_agency_payment_providers(agency_id,status);
create table if not exists logistics_agency_payments (payment_id text primary key, agency_id text not null, amount numeric not null, currency text not null, method text not null, provider_id text, external_reference text not null, sender_reference text, agency_shipment_id text, customer_reference text, terminal_id text, fee_amount numeric not null default 0, net_amount numeric not null, card_brand text, card_last4 text, status text not null, note text, recorded_by_owner_id text, settlement_id text, created_at timestamptz not null, updated_at timestamptz not null);
create unique index if not exists uq_agency_external_payment_ref on logistics_agency_payments(agency_id,external_reference);
create index if not exists idx_agency_payments_tenant_status on logistics_agency_payments(agency_id,status,created_at desc);
create table if not exists logistics_agency_payment_settlements (settlement_id text primary key, agency_id text not null, payment_ids jsonb not null, settlement_reference text not null, settled_amount numeric not null, fee_amount numeric not null default 0, net_settlement numeric not null, currency text not null, created_by_owner_id text, created_at timestamptz not null);
create index if not exists idx_agency_settlement_tenant on logistics_agency_payment_settlements(agency_id,created_at desc);
